{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

arguments.content:
{
  "watches": [
    {
      "name": "Core chrome and adding",
      "scenarios": [
        "features/todo-core.feature:Main and footer are hidden when there are no todos",
        "features/todo-core.feature:Main and footer appear when a todo is added",
        "features/todo-core.feature:Adding a todo creates an item in the list",
        "features/todo-core.feature:Empty trimmed input does not create a todo"
      ]
    },
    {
      "name": "Item toggling and counter",
      "scenarios": [
        "features/todo-item.feature:Completing a todo adds the completed class",
        "features/todo-item.feature:Uncompleting a todo removes the completed class",
        "features/todo-core.feature:Mark-all checkbox checks all todos",
        "features/todo-core.feature:Mark-all checkbox unchecks all todos when all are completed",
        "features/todo-core.feature:Mark-all checkbox reflects the state of individual toggles",
        "features/todo-core.feature:Counter shows the count of active todos",
        "features/todo-core.feature:Counter pluralises for zero items",
        "features/todo-core.feature:Counter pluralises for multiple items"
      ]
    },
    {
      "name": "Clear-completed and destroy",
      "scenarios": [
        "features/todo-core.feature:Clear-completed removes all completed todos",
        "features/todo-core.feature:Clear-completed button is hidden when no todo is completed",
        "features/todo-core.feature:Clear-completed button is visible when at least one todo is completed",
        "features/todo-item.feature:Clicking destroy removes the todo from the list"
      ]
    },
    {
      "name": "Editing",
      "scenarios": [
        "features/todo-editing.feature:Double-clicking a todo label activates editing mode",
        "features/todo-editing.feature:Pressing Enter saves the edited title",
        "features/todo-editing.feature:Blurring the edit input saves the title",
        "features/todo-editing.feature:Clearing the title and pressing Enter destroys the todo",
        "features/todo-editing.feature:Clearing the title and blurring destroys the todo",
        "features/todo-editing.feature:Pressing Escape discards the edit and restores the original title"
      ]
    },
    {
      "name": "Persistence",
      "scenarios": [
        "features/persistence.feature:Newly created todos are persisted to localStorage",
        "features/persistence.feature:Completed state is persisted to localStorage",
        "features/persistence.feature:Persisted todos are restored on reload",
        "features/persistence.feature:Editing mode is not persisted",
        "features/persistence.feature:Destroyed todos are removed from localStorage"
      ]
    },
    {
      "name": "Routing",
      "scenarios": [
        "features/routing.feature:Default route shows all todos",
        "features/routing.feature:Active route shows only incomplete todos",
        "features/routing.feature:Completed route shows only complete todos",
        "features/routing.feature:The selected class toggles on filter links",
        "features/routing.feature:Completing an active todo hides it in the active filter",
        "features/routing.feature:Uncompleting a completed todo hides it in the completed filter",
        "features/routing.feature:Active filter is preserved on reload"
      ]
    }
  ]
}

arguments.command:
cd /home/exedev/shipshape-shakedown/.eval-scratch/todomvc-newsim-01/sim && echo "=== Scenarios in features ===" && grep -n 'Scenario:' features/*.feature | sed 's/^/  /' && echo "" && echo "=== Scenarios in watchbill ===" && node -e "
const wb = JSON.parse(require('fs').readFileSync('watchbill.json','utf8'));
const all = wb.watches.flatMap(w => w.scenarios);
all.forEach(s => console.log('  ' + s));
console.log('Total: ' + all.length);
"
